from google.adk.agents import Agent


def classify(text: str) -> dict:
    return {"category": "technical" if "login" in text.lower() else "general"}


root_agent = Agent(name="helpdesk", model="gemini-3.5-flash", instruction="Classify requests using the tool. Do not claim to create tickets.", tools=[classify])

