import json
from pathlib import Path
import sys


def verify(path):
    events = [json.loads(line[5:]) for line in Path(path).read_text().splitlines() if line.startswith('data:')]
    parts = [part for event in events for part in event.get('content', {}).get('parts', [])]
    if not any(part.get('functionResponse', {}).get('name') == 'classify' for part in parts):
        raise ValueError('tool response missing')
    if not any(part.get('text') for part in parts):
        raise ValueError('answer missing')
    return True

if __name__ == '__main__':
    verify(sys.argv[1])

